def utc_now() -> str:
    return datetime.now(timezone.utc).replace(microsecond=0).isoformat().replace("+00:00", "Z")


def rel(path: Path) -> str:
    try:
        return str(path.relative_to(ROOT))
    except ValueError:
        return str(path)


def run_git(args: list[str], *, timeout_seconds: float = 3.0) -> str:
    try:
        proc = subprocess.Popen(
            ["git", "--no-pager", *args],
            cwd=ROOT,
            env={
                **os.environ,
                "GIT_TERMINAL_PROMPT": "0",
                "GIT_PAGER": "cat",
                "GIT_OPTIONAL_LOCKS": "0",
            },
            stdout=subprocess.PIPE,
            stderr=subprocess.DEVNULL,
            text=True,
            start_new_session=True,
        )
        stdout, _stderr = proc.communicate(timeout=timeout_seconds)
    except subprocess.TimeoutExpired:
        try:
            os.killpg(proc.pid, signal.SIGKILL)
            proc.communicate(timeout=1)
        except Exception:
            pass
        return "unavailable"
    except OSError:
        return "unavailable"
    if proc.returncode != 0:
        return "unavailable"
    return stdout.strip()


def sha256_file(path: Path) -> str | None:
    if not path.exists() or not path.is_file():
        return None
    digest = hashlib.sha256()
    try:
        with path.open("rb") as handle:
            for chunk in iter(lambda: handle.read(1024 * 1024), b""):
                digest.update(chunk)
    except OSError:
        return None
    return digest.hexdigest()


def stable_id(*parts: Any) -> str:
    raw = "|".join("" if part is None else str(part) for part in parts)
    return hashlib.sha1(raw.encode("utf-8")).hexdigest()[:24]


def read_json(path: Path) -> Any:
    return json.loads(path.read_text(encoding="utf-8"))


def read_json_if_readable(path: Path) -> dict[str, Any]:
    try:
        payload = read_json(path)
    except (OSError, json.JSONDecodeError):
        return {}
    return payload if isinstance(payload, dict) else {}


def broad_quality_artifact_tag(prefix: str) -> str:
    stem = "BROAD_LIVE_AS_IF_REPLAY_"
    if prefix.startswith(stem):
        return prefix[len(stem) :]
    if prefix == "BROAD_LIVE_AS_IF_REPLAY":
        return ""
    return prefix


def broad_quality_behavior_summary_path(prefix: str) -> Path:
    exact = ROUTE / f"{prefix}_BEHAVIOR_COMPARISON_SUMMARY.json"
    if exact.exists() and exact.stat().st_size > 0:
        return exact
    current_tag = broad_quality_artifact_tag(prefix)
    candidates = sorted(
        ROUTE.glob(f"{current_tag}_VS_*_BEHAVIOR_COMPARISON_SUMMARY.json"),
        key=lambda path: (path.stat().st_mtime, path.name),
        reverse=True,
    )
    if candidates:
        return candidates[0]
    # macOS-safe bounded comparison filenames may no longer contain the full
    # replay tag. Resolve those from the structured producer authority instead
    # of guessing from a truncated filename.
    bounded_candidates = sorted(
        ROUTE.glob("*_BEHAVIOR_COMPARISON_SUMMARY.json"),
        key=lambda path: (path.stat().st_mtime, path.name),
        reverse=True,
    )
    for path in bounded_candidates:
        payload = read_json_if_readable(path)
        producer_prefix = str(
            payload.get("repair_prefix")
            or payload.get("candidate_prefix")
            or ""
        ).strip()
        if producer_prefix == prefix:
            return path
    return exact


def broad_quality_summary_completed(summary_payload: Mapping[str, Any]) -> bool:
    return (
        summary_payload.get("status")
        == "broad_live_as_if_replay_materialized_broker_live_closed"
        and summary_payload.get("live_broker_authority") is False
        and summary_payload.get("broker_mutation_enabled") is False
        and summary_payload.get("final_selection_claim") is False
    )


def broad_quality_summary_sort_key(path: Path) -> tuple[str, float, str]:
    try:
        mtime = path.stat().st_mtime
    except OSError:
        mtime = 0.0
    return "", mtime, path.name


