def broad_quality_holdout_profile_rows(
    summary_payload: Mapping[str, Any],
) -> list[dict[str, Any]]:
    return [
        row
        for row in (summary_payload.get("split_profile_stats") or [])
        if isinstance(row, dict) and row.get("split") == "holdout"
    ]


def broad_quality_profile_priority(profile: Any) -> int:
    return BROAD_QUALITY_PROFILE_PRIORITY.get(str(profile or ""), 0)


def broad_quality_best_holdout_profile(
    summary_payload: Mapping[str, Any],
) -> dict[str, Any]:
    rows = broad_quality_holdout_profile_rows(summary_payload)
    if not rows:
        return {}
    return max(
        rows,
        key=lambda row: (
            broad_quality_profile_priority(row.get("profile")),
            int(row.get("trading_days") or 0),
            int(row.get("trade_rows") or row.get("filled_trade_count") or 0),
            float(numeric_or_none(row.get("net_r")) or -10**12),
        ),
    )


def broad_quality_holdout_day_counts(
    summary_payload: Mapping[str, Any],
    holdout_row: Mapping[str, Any] | None = None,
) -> tuple[int, int]:
    days_by_split = summary_payload.get("days_by_split") or {}
    holdout_days = days_by_split.get("holdout") if isinstance(days_by_split, Mapping) else []
    listed_holdout_days = len(holdout_days or [])
    row_holdout_days = int((holdout_row or {}).get("trading_days") or 0)
    selected_holdout_days = max(listed_holdout_days, row_holdout_days)
    full_available = summary_payload.get("full_available_days_by_split") or {}
    holdout_available = (
        full_available.get("holdout") if isinstance(full_available, Mapping) else {}
    ) or {}
    full_holdout_days = int(holdout_available.get("day_count") or 0)
    return selected_holdout_days, full_holdout_days


def broad_quality_holdout_stress_net_r(
    holdout_row: Mapping[str, Any],
    stress_id: str,
) -> float | None:
    stress = holdout_row.get("stress") or {}
    rows = stress.get("guarded_stress_rows") if isinstance(stress, Mapping) else []
    for row in rows or []:
        if isinstance(row, Mapping) and row.get("stress_id") == stress_id:
            return numeric_or_none(row.get("net_r"))
    return None


def broad_quality_candidate_score(
    prefix: str,
    summary_path: Path,
    summary_payload: Mapping[str, Any],
) -> tuple[int, int, float, int, int, int, int, float, str]:
    holdout_row = broad_quality_best_holdout_profile(summary_payload)
    selected_holdout_days, full_holdout_days = broad_quality_holdout_day_counts(
        summary_payload,
        holdout_row,
    )
    holdout_coverage_full = (
        full_holdout_days > 0 and selected_holdout_days == full_holdout_days
    )
    net_r = numeric_or_none(holdout_row.get("net_r"))
    stress_010 = broad_quality_holdout_stress_net_r(
        holdout_row,
        "extra_cost_0.10r_per_trade",
    )
    try:
        mtime = summary_path.stat().st_mtime
    except OSError:
        mtime = 0.0
    parity_complete, parity_missing = broad_quality_candidate_index_parity_health(
        prefix,
        summary_payload,
    )
    return (
        1 if parity_complete else 0,
        -parity_missing,
        mtime,
        1 if holdout_coverage_full else 0,
        broad_quality_profile_priority(holdout_row.get("profile")),
        selected_holdout_days,
        int(holdout_row.get("trade_rows") or holdout_row.get("filled_trade_count") or 0),
        1 if stress_010 is not None and stress_010 >= 0.0 else 0,
        float(net_r if net_r is not None else -10**12),
        mtime,
        prefix,
    )


def broad_quality_uses_exact_relational_candidate_surface(
    summary_payload: Mapping[str, Any],
) -> bool:
    """Return whether missed/order/trade exactly replace candidate serialization."""

    if not (
        summary_payload.get("candidate_ledger_omitted") is True
        and summary_payload.get("candidate_index_ledger_omitted") is True
    ):
        return False
    relational = summary_payload.get("candidate_relational_materialization")
    if not isinstance(relational, Mapping):
        return False
    candidate_rows = int(summary_payload.get("candidate_rows") or 0)
    relational_rows = int(relational.get("candidate_rows") or 0)
    relational_unique = int(
        relational.get("candidate_unique_profile_scoped_instance_keys") or 0
    )
    terminal_unique = int(
        relational.get("terminal_union_unique_profile_scoped_instance_keys") or 0
    )
    missing_counts = relational.get("missing_instance_key_counts")
    missing_counts = missing_counts if isinstance(missing_counts, Mapping) else {}
    return bool(
        relational.get("schema")
        == "gtos.final_moonshot.broad_replay.candidate_relational_materialization.v1"
        and relational.get("enabled") is True
        and relational.get("exact") is True
        and relational.get("status")
        == "exact_candidate_equals_missed_order_trade_union"
        and candidate_rows > 0
        and candidate_rows == relational_rows == relational_unique == terminal_unique
        and int(relational.get("candidate_duplicate_profile_scoped_instance_rows") or 0)
        == 0
        and int(relational.get("candidate_minus_terminal_union_count") or 0) == 0
        and int(relational.get("terminal_union_minus_candidate_count") or 0) == 0
        and {"candidate", "missed", "order", "trade"}.issubset(missing_counts)
        and not any(int(value or 0) for value in missing_counts.values())
    )


def broad_quality_relational_candidate_paths(prefix: str) -> tuple[Path, ...]:
    return tuple(
        ROUTE / f"{prefix}_{suffix}_LEDGER.jsonl"
        for suffix in ("MISSED_OPPORTUNITY", "ORDER", "TRADE")
    )


def broad_quality_candidate_index_parity_health(
    prefix: str,
    summary_payload: Mapping[str, Any],
) -> tuple[bool, int]:
    if broad_quality_uses_exact_relational_candidate_surface(summary_payload):
        return (
            all(
                path.exists() and path.stat().st_size > 0
                for path in broad_quality_relational_candidate_paths(prefix)
            ),
            0,
        )
    candidate_name = (
        f"{prefix}_CANDIDATE_INDEX_LEDGER.jsonl"
        if summary_payload.get("candidate_ledger_omitted") is True
        else f"{prefix}_CANDIDATE_LEDGER.jsonl"
    )
    candidate_path = ROUTE / candidate_name
    if not candidate_path.exists() or candidate_path.stat().st_size <= 0:
        return False, len(BROAD_QUALITY_REQUIRED_CANDIDATE_PARITY_FIELDS)
    max_rows = None
    try:
        candidate_size = candidate_path.stat().st_size
    except OSError:
        candidate_size = 0
    if candidate_size > BROAD_QUALITY_CANDIDATE_PARITY_HEALTH_MAX_FULL_SCAN_BYTES:
        max_rows = BROAD_QUALITY_CANDIDATE_PARITY_HEALTH_SAMPLE_ROWS
    missing = 0
    rows = 0
    try:
        for row in iter_jsonl(candidate_path):
            rows += 1
            for field in BROAD_QUALITY_REQUIRED_CANDIDATE_PARITY_FIELDS:
                if row.get(field) in (None, ""):
                    missing += 1
            if max_rows is not None and rows >= max_rows:
                break
    except TimeoutError:
        return False, len(BROAD_QUALITY_REQUIRED_CANDIDATE_PARITY_FIELDS)
    return rows > 0 and missing == 0, missing


def broad_holdout_gate_candidate_score(
    prefix: str,
    summary_path: Path,
    summary_payload: Mapping[str, Any],
) -> tuple[int, int, int, int, int, float, int, float, str]:
    holdout_row = broad_quality_best_holdout_profile(summary_payload)
    selected_holdout_days, full_holdout_days = broad_quality_holdout_day_counts(
        summary_payload,
        holdout_row,
    )
    holdout_coverage_full = (
        full_holdout_days > 0 and selected_holdout_days == full_holdout_days
    )
    net_r = numeric_or_none(holdout_row.get("net_r"))
    stress_010 = broad_quality_holdout_stress_net_r(
        holdout_row,
        "extra_cost_0.10r_per_trade",
    )
    trade_count = int(
        holdout_row.get("trade_rows") or holdout_row.get("filled_trade_count") or 0
    )
    try:
        mtime = summary_path.stat().st_mtime
    except OSError:
        mtime = 0.0
    return (
        1 if holdout_coverage_full else 0,
        1 if net_r is not None and net_r >= 0.0 else 0,
        1 if stress_010 is not None and stress_010 >= 0.0 else 0,
        broad_quality_profile_priority(holdout_row.get("profile")),
        selected_holdout_days,
        float(net_r if net_r is not None else -10**12),
        trade_count,
        mtime,
        prefix,
    )


def broad_quality_parity_manifest_files(prefix: str, tag: str) -> list[str]:
    suffix = f"_{tag}" if tag else ""
    fallback = {
        "big_r_provenance_breakdown": f"BIG_R_PROVENANCE_BREAKDOWN{suffix}.json",
        "source_bound_to_executed_parity_ledger": (
            f"SOURCE_BOUND_TO_EXECUTED_PARITY{suffix}_LEDGER.jsonl"
        ),
        "source_bound_to_executed_parity_summary": (
            f"SOURCE_BOUND_TO_EXECUTED_PARITY{suffix}_SUMMARY.json"
        ),
        "candidate_instance_parity_projection_ledger": (
            f"CANDIDATE_INSTANCE_PARITY_PROJECTION{suffix}_LEDGER.jsonl"
        ),
        "execution_leakage_bucket_ledger": (
            f"EXECUTION_LEAKAGE_BUCKET{suffix}_LEDGER.jsonl"
        ),
        "execution_leakage_repair_plan": (
            f"EXECUTION_LEAKAGE_REPAIR_PLAN{suffix}.json"
        ),
    }
    default_summary = ROUTE / fallback[
        "source_bound_to_executed_parity_summary"
    ]
    candidates = [default_summary]
    candidates.extend(
        path
        for path in ROUTE.glob("SOURCE_BOUND_TO_EXECUTED_PARITY*_SUMMARY.json")
        if path != default_summary
    )
    producer_summary: Mapping[str, Any] = {}
    producer_summary_path: Path | None = None
    for path in sorted(
        candidates,
        key=lambda item: (
            item.stat().st_mtime if item.exists() else -1.0,
            item.name,
        ),
        reverse=True,
    ):
        payload = read_json_if_readable(path)
        exact_transfer = payload.get("exact_replay_window_transfer")
        exact_transfer = (
            exact_transfer if isinstance(exact_transfer, Mapping) else {}
        )
        producer_prefix = str(
            payload.get("broad_replay_prefix")
            or exact_transfer.get("broad_replay_prefix")
            or ""
        )
        if producer_prefix != prefix:
            continue
        producer_summary = payload
        producer_summary_path = path
        break
    if producer_summary_path is None:
        return list(fallback.values())

    artifacts = producer_summary.get("artifacts")
    artifacts = artifacts if isinstance(artifacts, Mapping) else {}
    files: list[str] = []
    for key, fallback_name in fallback.items():
        if key == "source_bound_to_executed_parity_summary":
            files.append(producer_summary_path.name)
            continue
        reference = str(artifacts.get(key) or "").strip()
        files.append(Path(reference).name if reference else fallback_name)
    return files


def broad_quality_required_manifest_files(prefix: str, tag: str) -> list[str]:
    summary = read_json_if_readable(ROUTE / f"{prefix}_SUMMARY.json")
    files = [
        f"{prefix}_SOURCE_UNIVERSE_LEDGER.jsonl",
        f"{prefix}_DECISION_LEDGER.jsonl",
        f"{prefix}_SCORECARD_LEDGER.jsonl",
        f"{prefix}_ORDER_LEDGER.jsonl",
        f"{prefix}_TRADE_LEDGER.jsonl",
        f"{prefix}_ORDERED_PATH_ORACLE_LEDGER.jsonl",
        f"{prefix}_MISSED_OPPORTUNITY_LEDGER.jsonl",
        f"{prefix}_BUCKET_LEDGER.jsonl",
        f"{prefix}_SUMMARY.json",
    ]
    if int(summary.get("comparison_ledger_rows") or 0) > 0:
        files.append(f"{prefix}_COMPARISON_LEDGER.jsonl")
    if broad_quality_uses_exact_relational_candidate_surface(summary):
        pass
    elif summary.get("candidate_ledger_omitted") is True:
        files.append(f"{prefix}_CANDIDATE_INDEX_LEDGER.jsonl")
    else:
        files.append(f"{prefix}_CANDIDATE_LEDGER.jsonl")
    if summary.get("packet_sidecar_ledger_omitted") is not True:
        files.append(f"{prefix}_PACKET_SIDECAR_LEDGER.jsonl")
    required_parity_files = broad_quality_parity_manifest_files(prefix, tag)
    optional_files = [
        f"{prefix}_CANDIDATE_INDEX_POI_REHYDRATION_RESULT.json",
        f"{prefix}_TERMINAL_CANDIDATE_COST_ALIAS_REPAIR_SUMMARY.json",
        f"{prefix}_FLOW_DIAGNOSTIC_SUMMARY.json",
        f"{prefix}_FLOW_BUCKET_LEDGER.jsonl",
        f"{prefix}_FLOW_DIAGNOSTIC_DOSSIER.md",
        f"{prefix}_BEHAVIOR_COMPARISON_SUMMARY.json",
        f"{prefix}_BEHAVIOR_DOSSIER.md",
        f"{prefix}_COST_DELTA_SUMMARY.json",
        f"{prefix}_COST_DELTA_LEDGER.jsonl",
    ]
    behavior_summary_path = broad_quality_behavior_summary_path(prefix)
    if behavior_summary_path.exists() and behavior_summary_path.stat().st_size > 0:
        optional_files.append(behavior_summary_path.name)
        behavior_payload = read_json_if_readable(behavior_summary_path)
        behavior_artifacts = behavior_payload.get("artifacts")
        behavior_artifacts = (
            behavior_artifacts if isinstance(behavior_artifacts, Mapping) else {}
        )
        dossier_reference = str(
            behavior_artifacts.get("behavior_dossier") or ""
        ).strip()
        if dossier_reference:
            dossier_path = ROUTE / Path(dossier_reference).name
            if dossier_path.exists() and dossier_path.stat().st_size > 0:
                optional_files.append(dossier_path.name)
        for artifact_key in (
            "baseline_summary",
            "baseline_trade_ledger",
            "baseline_parity_summary",
        ):
            reference = str(behavior_artifacts.get(artifact_key) or "").strip()
            if not reference:
                continue
            input_path = ROUTE / Path(reference).name
            if input_path.exists() and input_path.stat().st_size > 0:
                optional_files.append(input_path.name)
    files.extend(required_parity_files)
    flow_summary_name = f"{prefix}_FLOW_DIAGNOSTIC_SUMMARY.json"
    flow_bucket_name = f"{prefix}_FLOW_BUCKET_LEDGER.jsonl"
    flow_summary_present = (
        (ROUTE / flow_summary_name).exists()
        and (ROUTE / flow_summary_name).stat().st_size > 0
    )
    for filename in optional_files:
        path = ROUTE / filename
        if path.exists() and path.stat().st_size > 0:
            files.append(filename)
        elif filename == flow_bucket_name and flow_summary_present:
            # A flow summary is not self-contained: its bucket_row_count and
            # rollups are physically verified against the paired ledger.
            files.append(filename)
    return files


def broad_quality_pinned_prefixes_from_disk() -> list[str]:
    explicit = os.environ.get("GTOS_BROAD_QUALITY_PARITY_PREFIX", "").strip()
    if explicit:
        return [explicit]
    prefixes: list[str] = []
    seen: set[str] = set()
    for path in (ROUTE / "OUTPUT_MANIFEST.json", ROUTE / "VERIFICATION_RESULT.json"):
        payload = read_json_if_readable(path)
        for key in (
            "broad_quality_parity_prefix",
            "broad_live_as_if_quality_parity_prefix",
        ):
            prefix = str(payload.get(key) or "").strip()
            if prefix and prefix not in seen:
                seen.add(prefix)
                prefixes.append(prefix)
    return prefixes


def current_root_cause_map_payload() -> Mapping[str, Any]:
    pointer_path = ROOT / ".context/context_os/CURRENT_ROOT_CAUSE_MAP.json"
    payload = read_json_if_readable(pointer_path)
    if not payload:
        return {}
    target = str(payload.get("current_root_cause_map") or "").strip()
    if not target:
        return payload
    target_path = ROOT / target
    target_payload = read_json_if_readable(target_path)
    return target_payload or payload


def current_root_cause_map_broad_quality_prefixes() -> list[str]:
    payload = current_root_cause_map_payload()
    prefixes: list[str] = []
    seen: set[str] = set()

    def add_prefix(prefix: Any) -> None:
        value = str(prefix or "").strip()
        if not value or value in seen:
            return
        if not (ROUTE / f"{value}_SUMMARY.json").exists():
            return
        seen.add(value)
        prefixes.append(value)

    add_prefix(payload.get("latest_completed_replay_prefix"))
    latest = payload.get("latest_completed_replay")
    if isinstance(latest, Mapping):
        add_prefix(latest.get("prefix"))
    latest_targeted = payload.get("latest_completed_targeted_replay")
    if isinstance(latest_targeted, Mapping):
        add_prefix(latest_targeted.get("prefix"))
    add_prefix(payload.get("broad_quality_parity_prefix"))
    add_prefix(payload.get("active_broad_quality_parity_prefix"))
    return prefixes


def broad_quality_prefix_complete_for_selection(prefix: str) -> bool:
    tag = broad_quality_artifact_tag(prefix)
    summary = read_json_if_readable(ROUTE / f"{prefix}_SUMMARY.json")
    if not broad_quality_summary_completed(summary):
        return False
    packet_omitted = summary.get("packet_sidecar_ledger_omitted") is True
    relational_candidate_surface = broad_quality_uses_exact_relational_candidate_surface(
        summary
    )
    if relational_candidate_surface:
        if not all(
            path.exists() and path.stat().st_size > 0
            for path in broad_quality_relational_candidate_paths(prefix)
        ):
            return False
    else:
        candidate_name = (
            f"{prefix}_CANDIDATE_INDEX_LEDGER.jsonl"
            if summary.get("candidate_ledger_omitted") is True
            else f"{prefix}_CANDIDATE_LEDGER.jsonl"
        )
        if not (ROUTE / candidate_name).exists():
            return False
    if not packet_omitted and not (ROUTE / f"{prefix}_PACKET_SIDECAR_LEDGER.jsonl").exists():
        return False
    return all(
        (ROUTE / filename).exists()
        and (ROUTE / filename).stat().st_size > 0
        for filename in broad_quality_required_manifest_files(prefix, tag)
    )


def iter_candidate_broad_quality_prefixes() -> list[str]:
    explicit = os.environ.get("GTOS_BROAD_QUALITY_PARITY_PREFIX", "").strip()
    if explicit:
        return [explicit]
    prefixes: list[str] = []
    seen: set[str] = set()
    current_root_prefixes = current_root_cause_map_broad_quality_prefixes()
    for prefix in current_root_prefixes:
        if prefix not in seen:
            seen.add(prefix)
            prefixes.append(prefix)
    for prefix in broad_quality_pinned_prefixes_from_disk():
        if prefix not in seen:
            seen.add(prefix)
            prefixes.append(prefix)
    exhaustive = os.environ.get("GTOS_BROAD_QUALITY_EXHAUSTIVE_PREFIX_SCAN", "")
    exhaustive_enabled = exhaustive in {"1", "true", "TRUE", "yes", "YES"}
    current_root_complete = any(
        broad_quality_prefix_complete_for_selection(prefix)
        for prefix in current_root_prefixes
    )
    if current_root_complete and not exhaustive_enabled:
        return prefixes
    summary_paths = [
        path
        for path in ROUTE.glob("BROAD_LIVE_AS_IF_REPLAY*_SUMMARY.json")
    ]
    if current_root_prefixes and not exhaustive_enabled:
        try:
            recent_limit = int(os.environ.get("GTOS_BROAD_QUALITY_RECENT_PREFIX_SCAN_LIMIT") or 12)
        except ValueError:
            recent_limit = 12
        summary_paths = sorted(
            summary_paths,
            key=broad_quality_summary_sort_key,
            reverse=True,
        )[: max(1, recent_limit)]
    else:
        summary_paths = sorted(
            summary_paths,
            key=broad_quality_summary_sort_key,
            reverse=True,
        )
    for path in summary_paths:
        prefix = path.name[: -len("_SUMMARY.json")]
        if prefix.endswith(
            (
                "_PARTIAL",
                "_FLOW_DIAGNOSTIC",
                "_BEHAVIOR_COMPARISON",
                "_COST_DELTA",
            )
        ):
            continue
        if prefix not in seen:
            seen.add(prefix)
            prefixes.append(prefix)
    return prefixes


def select_current_broad_quality_prefix() -> tuple[str, str]:
    explicit = os.environ.get("GTOS_BROAD_QUALITY_PARITY_PREFIX", "").strip()
    selected: tuple[
        tuple[int, int, float, int, int, int, int, int, float, str],
        str,
        str,
    ] | None = None
    exhaustive = os.environ.get("GTOS_BROAD_QUALITY_EXHAUSTIVE_PREFIX_SCAN", "")
    exhaustive_enabled = exhaustive in {"1", "true", "TRUE", "yes", "YES"}
    if not explicit and not exhaustive_enabled:
        for current_prefix in current_root_cause_map_broad_quality_prefixes():
            if broad_quality_prefix_complete_for_selection(current_prefix):
                return current_prefix, broad_quality_artifact_tag(current_prefix)
    prefixes = [explicit] if explicit else iter_candidate_broad_quality_prefixes()
    for prefix in prefixes:
        if not prefix:
            continue
        tag = broad_quality_artifact_tag(prefix)
        summary_path = ROUTE / f"{prefix}_SUMMARY.json"
        summary = read_json_if_readable(summary_path)
        if not broad_quality_summary_completed(summary):
            continue
        packet_omitted = summary.get("packet_sidecar_ledger_omitted") is True
        if (
            summary.get("candidate_ledger_omitted") is not True
            and not (ROUTE / f"{prefix}_CANDIDATE_LEDGER.jsonl").exists()
        ):
            continue
        if not packet_omitted and not (ROUTE / f"{prefix}_PACKET_SIDECAR_LEDGER.jsonl").exists():
            continue
        if any(
            not (ROUTE / filename).exists()
            or (ROUTE / filename).stat().st_size <= 0
            for filename in broad_quality_required_manifest_files(prefix, tag)
        ):
            continue
        if explicit:
            return prefix, tag
        score = broad_quality_candidate_score(prefix, summary_path, summary)
        if selected is None or score > selected[0]:
            selected = (score, prefix, tag)
    if selected is not None:
        return selected[1], selected[2]
    fallback = os.environ.get(
        "GTOS_BROAD_QUALITY_PARITY_PREFIX",
        "BROAD_LIVE_AS_IF_REPLAY_FIELD_PARITY_RESTORED_REPAIR_SMOKE",
    ).strip()
    return fallback, broad_quality_artifact_tag(fallback)


def current_broad_quality_summary_relpath() -> str:
    prefix, _tag = select_current_broad_quality_prefix()
    return rel(ROUTE / f"{prefix}_SUMMARY.json")


def broad_holdout_gate_minimum_files_exist(prefix: str) -> bool:
    required = [
        ROUTE / f"{prefix}_SUMMARY.json",
        ROUTE / f"{prefix}_ORDER_LEDGER.jsonl",
        ROUTE / f"{prefix}_TRADE_LEDGER.jsonl",
        ROUTE / f"{prefix}_BUCKET_LEDGER.jsonl",
    ]
    return all(path.exists() and path.stat().st_size > 0 for path in required)


def select_current_broad_holdout_gate_prefix() -> tuple[str, str]:
    explicit = os.environ.get("GTOS_BROAD_HOLDOUT_GATE_PREFIX", "").strip()
    if not explicit:
        manifest = read_json_if_readable(ROUTE / "OUTPUT_MANIFEST.json")
        manifest_prefix = str(manifest.get("broad_holdout_gate_prefix") or "").strip()
        if manifest_prefix:
            summary_path = ROUTE / f"{manifest_prefix}_SUMMARY.json"
            summary = read_json_if_readable(summary_path)
            if (
                broad_quality_summary_completed(summary)
                and broad_quality_best_holdout_profile(summary)
                and broad_holdout_gate_minimum_files_exist(manifest_prefix)
            ):
                return manifest_prefix, broad_quality_artifact_tag(manifest_prefix)
    selected: tuple[
        tuple[int, int, int, int, int, float, int, float, str],
        str,
        str,
    ] | None = None
    prefixes = [explicit] if explicit else iter_candidate_broad_quality_prefixes()
    for prefix in prefixes:
        if not prefix:
            continue
        tag = broad_quality_artifact_tag(prefix)
        summary_path = ROUTE / f"{prefix}_SUMMARY.json"
        summary = read_json_if_readable(summary_path)
        if not broad_quality_summary_completed(summary):
            continue
        if not broad_quality_best_holdout_profile(summary):
            continue
        if not broad_holdout_gate_minimum_files_exist(prefix):
            continue
        if explicit:
            return prefix, tag
        score = broad_holdout_gate_candidate_score(prefix, summary_path, summary)
        if selected is None or score > selected[0]:
            selected = (score, prefix, tag)
    if selected is not None:
        return selected[1], selected[2]
    return select_current_broad_quality_prefix()


def stable_generated_utc(path: Path, data: dict[str, Any]) -> str:
    def strip_generated_utc(row: dict[str, Any]) -> dict[str, Any]:
        return {
            key: value
            for key, value in row.items()
            if key not in {"generated_utc", "packet_hash_sha256"}
        }

    candidate_payloads: list[dict[str, Any]] = []
    head_payload = run_git(["show", f"HEAD:{rel(path)}"])
    if head_payload != "unavailable":
        try:
            candidate_payloads.append(json.loads(head_payload))
        except json.JSONDecodeError:
            pass
    if path.exists():
        try:
            candidate_payloads.append(read_json(path))
        except json.JSONDecodeError:
            pass
    for existing in candidate_payloads:
        if strip_generated_utc(existing) == strip_generated_utc(data):
            return existing.get("generated_utc") or data.get("generated_utc") or utc_now()
    return data.get("generated_utc") or utc_now()


def route_packet_hash(payload: Any) -> str:
    material = json.dumps(payload, sort_keys=True, separators=(",", ":"), default=str)
    return hashlib.sha256(material.encode("utf-8")).hexdigest()


def retimestamp_and_rehash_row(row: dict[str, Any], generated_utc: str) -> dict[str, Any]:
    if "generated_utc" in row:
        row["generated_utc"] = generated_utc
    if "row_hash_sha256" in row:
        row.pop("row_hash_sha256", None)
        row["row_hash_sha256"] = route_packet_hash(row)
    if "packet_hash_sha256" in row:
        row.pop("packet_hash_sha256", None)
        row["packet_hash_sha256"] = route_packet_hash(row)
    return row


def retimestamp_artifact_bundle(
    bundle: dict[str, Any],
    *,
    generated_utc: str,
) -> dict[str, Any]:
    """Reuse an already-materialized artifact bundle with a stable timestamp.

    Large replay-authority builders can materialize multi-GB candidate surfaces.
    The route only needs a second pass for stable generated_utc/hash values, so
    retimestamp the existing rows instead of recomputing package evaluation.
    """

    for value in bundle.values():
        if isinstance(value, dict):
            retimestamp_and_rehash_row(value, generated_utc)
        elif isinstance(value, list):
            for item in value:
                if isinstance(item, dict):
                    retimestamp_and_rehash_row(item, generated_utc)
    return bundle


def iter_jsonl_text_lines(
    path: Path,
    *,
    max_read_retries: int = 1200,
    reopen_after_timeout_streak: int = 20,
) -> Iterable[str]:
    """Yield JSONL text lines while recovering from transient file timeouts."""

    if path.suffix == ".gz":
        with gzip.open(path, "rt", encoding="utf-8") as handle:
            while True:
                try:
                    line = handle.readline()
                except TimeoutError as exc:
                    if max_read_retries <= 0:
                        raise TimeoutError(
                            f"timed out reading {path}"
                        ) from exc
                    max_read_retries -= 1
                    time.sleep(0.5)
                    continue
                if not line:
                    break
                yield line
        return
    offset = 0
    timeout_streak = 0
    while True:
        try:
            with path.open("rb") as handle:
                handle.seek(offset)
                while True:
                    try:
                        current_size = path.stat().st_size
                    except OSError:
                        current_size = None
                    if current_size is not None and offset >= current_size:
                        return
                    try:
                        raw_line = handle.readline()
                    except TimeoutError as exc:
                        if max_read_retries <= 0:
                            raise TimeoutError(
                                f"timed out reading {path} at byte offset {offset}"
                            ) from exc
                        max_read_retries -= 1
                        timeout_streak += 1
                        time.sleep(0.5)
                        if timeout_streak >= reopen_after_timeout_streak:
                            timeout_streak = 0
                            break
                        continue
                    timeout_streak = 0
                    if not raw_line:
                        return
                    offset = handle.tell()
                    yield raw_line.decode("utf-8", errors="replace")
        except TimeoutError:
            raise


def iter_jsonl(path: Path, *, max_read_retries: int = 1200) -> Iterable[dict[str, Any]]:
    for line in iter_jsonl_text_lines(path, max_read_retries=max_read_retries):
        if line.strip():
            yield json.loads(line)


def read_jsonl(path: Path) -> list[dict[str, Any]]:
    return list(iter_jsonl(path))


def read_jsonl_rows_if_exists(path: Path, *, max_read_retries: int = 1200) -> list[Any]:
    if not path.exists():
        return []
    rows: list[Any] = []
    for line in iter_jsonl_text_lines(path, max_read_retries=max_read_retries):
        if not line.strip():
            continue
        try:
            rows.append(json.loads(line))
        except json.JSONDecodeError:
            continue
    return rows


def phase2_m15_grid_expansion_candidate_authority_path() -> Path:
    raw_path = PHASE2_M15_GRID_EXPANSION_LEDGER_PATHS["candidate"]
    if raw_path.exists():
        return raw_path
    return PHASE2_M15_GRID_EXPANSION_LEDGER_PATHS["compact_candidate"]


def jsonl_row_count_if_exists(path: Path, *, max_read_retries: int = 1200) -> int:
    if not path.exists():
        return 0
    count = 0
    for line in iter_jsonl_text_lines(path, max_read_retries=max_read_retries):
        if line.strip():
            count += 1
    return count


